@pytest.mark.parametrize('case',OBSERVED,ids=lambda c:c['label'])
def test_observed_primitive_records_decode_exactly_and_preserve_bytes(case):
    data=bytes.fromhex(case['stream'])
    result=decode_component_stream(data,bytes.fromhex(case['wide']))
    assert result==case['expected']
    assert encode_component_stream(result)==data


def test_independent_nonfixture_geometry_and_rich_pad_authoring():
    footprint={
      'name':'Independent arbitrary component',
      'pads':[{'designator':'X42','x':-1.7,'y':2.9,'width':1.1,'height':.7,
               'rotation':37,'shape':'rectangle','layer':'Bottom Layer','is_plated':False,
               'hole_size':.3,'net_index':22,'component_index':9,
               'power_plane_connect_style':'direct','solder_mask_expansion_mode':'manual',
               'solder_mask_expansion':.08,'relief_entries':6}],
      'tracks':[{'x1':-7,'y1':8,'x2':9,'y2':-10,'width':.17,'layer':'Bottom Overlay',
                 'solder_mask_expansion':.04,'keepout_restrictions':3}],
      'arcs':[{'x':-3,'y':4,'radius':2.2,'width':.13,'start_angle':17,'end_angle':221}],
      'text':[{'text':'Ω independent','x':3,'y':-6,'height':.9,'rotation':23,
               'kind':'true_type','font_name':'Courier New','bold':True,
               'mirror':True,'justification':'middle_center'}],
    }
    data=encode_component_stream(footprint)
    result=decode_component_stream(data,encode_wide_strings(footprint))
    pad=result['pads'][0]
    assert pad['designator']=='X42' and pad['rotation']==37
    assert pad['layer']=='Bottom Layer' and pad['is_plated'] is False
    assert pad['net_index']==22 and pad['component_index']==9
    assert pad['power_plane_connect_style']=='direct'
    assert abs(pad['solder_mask_expansion']-.08)<.000002
    track=result['tracks'][0]
    assert track['keepout_restrictions']==3
    assert abs(track['x1']+7)<.000002
    assert result['arcs'][0]['start_angle']==17
    assert result['text'][0]['text']=='Ω independent'
    assert result['text'][0]['kind']=='true_type'
    assert result['text'][0]['justification']=='middle_center'
    assert result['text'][0]['font_name']=='Courier New'
    assert result['text'][0]['bold'] and result['text'][0]['mirror']


def test_edit_known_geometry_retains_unmodeled_block_bytes():
    case=next(c for c in OBSERVED if c['label']=='tracks')
    data=bytearray.fromhex(case['stream'])
    # The trailing reserved field has no modeled meaning.
    data[-1]=0xA5
    result=decode_component_stream(bytes(data))
    result['tracks'][0]['width']=.37
    result['tracks'][0]['x2']=-11.4
    encoded=encode_component_stream(result)
    assert encoded[-1]==0xA5
    again=decode_component_stream(encoded)
    assert abs(again['tracks'][0]['width']-.37)<.000002
    assert abs(again['tracks'][0]['x2']+11.4)<.000002


def test_polygon_holes_are_authored_independently():
    outer=[{'x':0,'y':0},{'x':7,'y':0},{'x':7,'y':8}]
    hole=[{'x':1,'y':1},{'x':2,'y':1},{'x':1.5,'y':2}]
    result=decode_component_stream(encode_component_stream({'name':'Hole','regions':[{'vertices':outer,'holes':[hole]}]}))
    assert len(result['regions'][0]['holes'])==1
    assert abs(result['regions'][0]['holes'][0][2]['x']-1.5)<.000002


def test_unknown_primitive_tail_is_explicitly_preserved_and_truncation_rejected():
    head=encode_component_stream({'name':'Unknown'})
    opaque=b'\xfa'+struct.pack('<I',4)+b'ABCD'
    result=decode_component_stream(head+opaque)
    assert result['unsupported_primitive_types']==[250]
    assert encode_component_stream(result)==head+opaque
    with pytest.raises(PcbPrimitiveError,match='exceeds'):
        decode_component_stream(head+b'\x04'+struct.pack('<I',500)+b'x')
